(1212080, 153364, 33361, '<td valign="top">lots of gray and some black but no stark white</td>', 'lots of gray and some black but no stark white', '2005-03-07 08:11:19.000000', NULL, 1),
(1212081, 152901, 32161, '<td valign="top">I feel if you had darkened the sky you could have won! still v good though.</td>', 'I feel if you had darkened the sky you could have won! still v good though.', '2005-03-07 08:11:20.000000', NULL, 1),
(1212084, 152852, 33361, '<td valign="top">I love this except the sky looks very pixelated..</td>', 'I love this except the sky looks very pixelated..', '2005-03-07 08:17:22.000000', NULL, 1),
