(1212087, 152484, 14012, '<td valign="top">this would be excellent if the highlights were not blown out on the bottom left petals</td>', 'this would be excellent if the highlights were not blown out on the bottom left petals', '2005-03-07 08:21:54.000000', NULL, 1),
(1212089, 152366, 12571, '<td valign="top">Daffodils in graveyard... Despite the spelling errors, I gave you a 10  :)</td>', 'Daffodils in graveyard... Despite the spelling errors, I gave you a 10  :)', '2005-03-07 08:22:39.000000', NULL, 1),
