(1212093, 153417, 25033, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2005-03-07 08:26:44.000000', NULL, 1),
(1212095, 152699, 33515, '<td valign="top">My feeling is that there is just on much white here for a AA type photo.</td>', 'My feeling is that there is just on much white here for a AA type photo.', '2005-03-07 08:27:33.000000', NULL, 1),
(1212096, 152484, 33515, '<td valign="top">Great reflection and detail of the flower</td>', 'Great reflection and detail of the flower', '2005-03-07 08:28:23.000000', NULL, 1),
(1212100, 151764, 33515, '<td valign="top">The gondola is distracting in this otherwise beautiful photo.</td>', 'The gondola is distracting in this otherwise beautiful photo.', '2005-03-07 08:30:27.000000', NULL, 1),
(1212101, 153219, 28337, '<td valign="top">not a very interesting picture</td>', 'not a very interesting picture', '2005-03-07 08:30:43.000000', NULL, 1),
