(1213577, 152363, 34103, '<td valign="top">Very nice, I think others might not like the blue tint.</td>', 'Very nice, I think others might not like the blue tint.', '2005-03-07 20:33:57.000000', NULL, 1),
(1213578, 152486, 34103, '<td valign="top">Good one. Like the composition. Its points to the zenith.</td>', 'Good one. Like the composition. Its points to the zenith.', '2005-03-07 20:35:11.000000', NULL, 1),
