(1213725, 151432, 33560, '<td valign="top">"Over the top."    I see this as a kind of caricture of the Ansel Adam''s sky.  It''s a stunning shot, and it fits the challlenge.</td>', '"Over the top."    I see this as a kind of caricture of the Ansel Adam''s sky.  It''s a stunning shot, and it fits the challlenge.', '2005-03-07 21:40:51.000000', NULL, 1),
(1213727, 153186, 25033, '<td valign="top">Good idea, but I don''t care for angle.  Should have been closer to the falls or further and less shadows.</td>', 'Good idea, but I don''t care for angle.  Should have been closer to the falls or further and less shadows.', '2005-03-07 21:41:25.000000', NULL, 1),
(1213735, 152471, 25033, '<td valign="top">Would have scored higher if it would have had either all of the tree or more cropped.</td>', 'Would have scored higher if it would have had either all of the tree or more cropped.', '2005-03-07 21:44:16.000000', NULL, 1),
(1213737, 151344, 25033, '<td valign="top">I know u have no control...but more clouds would have made this a really high scorer.  Good job!</td>', 'I know u have no control...but more clouds would have made this a really high scorer.  Good job!', '2005-03-07 21:45:33.000000', NULL, 1),
