INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1214508, 153292, 15919, '<td valign="top">Strange looking and original.  Oldish looking.</td>', 'Strange looking and original.  Oldish looking.', '2005-03-08 08:30:34.000000', NULL, 1),
(1214509, 153240, 15919, '<td valign="top">Good image but needs better editing.  Some working on curves and levels could have made it better.</td>', 'Good image but needs better editing.  Some working on curves and levels could have made it better.', '2005-03-08 08:31:34.000000', NULL, 1),
(1214515, 153257, 28337, '<td valign="top">did she get in on that try? <br/> <br/>being an EMT myself I realize its difficulty in taking any picture in that kind of setting. However I still think the cut off head of the two nurses/doctors in the background is distracting.  perhaps a wider angle including the two nurses would be better.</td>', 'did she get in on that try?  being an EMT myself I realize its difficulty in taking any picture in that kind of setting. However I still think the cut off head of the two nurses/doctors in the background is distracting.  perhaps a wider angle including the two nurses would be better.', '2005-03-08 08:35:09.000000', NULL, 1),
(1214517, 152044, 14620, '<td valign="top">This is exquisite.  Fabulous composition, I love the textures in the church and the contrasts are just right and the grain in the sky really adds to the feel of the shot.  Bumping to a 9</td>', 'This is exquisite.  Fabulous composition, I love the textures in the church and the contrasts are just right and the grain in the sky really adds to the feel of the shot.  Bumping to a 9', '2005-03-08 08:36:03.000000', NULL, 1),
(1214518, 152486, 14620, '<td valign="top">Wow!  Just Wow! :-)</td>', 'Wow!  Just Wow! :-)', '2005-03-08 08:36:52.000000', NULL, 1),
(1214526, 153117, 15711, '<td valign="top">Lovely shot!  Not the typical clouds or craggy rocks.  The contrast and angle of the shot is excellent! I like the architecture amidst the natural setting - all coated with snow.  Way to go!</td>', 'Lovely shot!  Not the typical clouds or craggy rocks.  The contrast and angle of the shot is excellent! I like the architecture amidst the natural setting - all coated with snow.  Way to go!', '2005-03-08 08:45:08.000000', NULL, 1),
(1214527, 152305, 15711, '<td valign="top">Very nice.  The eye following over the bridge is a great vantage point!!  Really an excellent photo.</td>', 'Very nice.  The eye following over the bridge is a great vantage point!!  Really an excellent photo.', '2005-03-08 08:45:54.000000', NULL, 1),
(1214530, 153329, 15711, '<td valign="top">VERY NICE! One of my favorites in this group. The softness of the billowy clouds are a nice backdrop to the more stiff skeletons of the cacti. Great contrast!! I''d hang this in my home.</td>', 'VERY NICE! One of my favorites in this group. The softness of the billowy clouds are a nice backdrop to the more stiff skeletons of the cacti. Great contrast!! I''d hang this in my home.', '2005-03-08 08:48:33.000000', NULL, 1),
(1214532, 152625, 29827, '<td valign="top">Almost looks like Mt Fuji...  Contrast makes the foreground a little too dark for me though.</td>', 'Almost looks like Mt Fuji...  Contrast makes the foreground a little too dark for me though.', '2005-03-08 08:49:17.000000', NULL, 1),
(1214533, 153074, 15711, '<td valign="top">Nice shot. I would have liked a bit more contrast in the sky. Nice angle and placement of the tree in the photo.</td>', 'Nice shot. I would have liked a bit more contrast in the sky. Nice angle and placement of the tree in the photo.', '2005-03-08 08:49:33.000000', NULL, 1),
(1214534, 153088, 29827, '<td valign="top">Nicely laid out, but the specks (dust?) detract from the image.</td>', 'Nicely laid out, but the specks (dust?) detract from the image.', '2005-03-08 08:49:54.000000', NULL, 1),
(1214537, 152484, 15711, '<td valign="top">Interesting and different.  VERY NICE!!!</td>', 'Interesting and different.  VERY NICE!!!', '2005-03-08 08:50:52.000000', NULL, 1),
(1214538, 152992, 29827, '<td valign="top">We have a winner here I reckon.  Definite top 5.  10 from me.</td>', 'We have a winner here I reckon.  Definite top 5.  10 from me.', '2005-03-08 08:51:05.000000', NULL, 1),
(1214539, 152852, 15711, '<td valign="top">Great placement of the opening in the forefront - almost like a duplicate of the one in the background.   Nice contrast. Really well done!</td>', 'Great placement of the opening in the forefront - almost like a duplicate of the one in the background.   Nice contrast. Really well done!', '2005-03-08 08:51:58.000000', NULL, 1),
(1214540, 152350, 29827, '<td valign="top">Nice image, nice frame.  Would have been interested to see how it would have been with longer exposure to even out the ripples which are a little distracting to me.  Top 5 I reckon though, 9 from me.</td>', 'Nice image, nice frame.  Would have been interested to see how it would have been with longer exposure to even out the ripples which are a little distracting to me.  Top 5 I reckon though, 9 from me.', '2005-03-08 08:52:22.000000', NULL, 1),
(1214545, 153469, 9089, '<td valign="top">Just coming back to comment on this photo.  To me, this is the best example of Ansel Adams like work.  The contrast, the whole spectrum from black to white is there.  My only minor nitpick to the picture is the tree intruding on the right side of the pciture.  That is minor, but if it hadn''t been there, this would be perfect.  Still giving a 10, because this picture has drawn me back and seems like it should be in the ribbons or top 10.</td>', 'Just coming back to comment on this photo.  To me, this is the best example of Ansel Adams like work.  The contrast, the whole spectrum from black to white is there.  My only minor nitpick to the picture is the tree intruding on the right side of the pciture.  That is minor, but if it hadn''t been there, this would be perfect.  Still giving a 10, because this picture has drawn me back and seems like it should be in the ribbons or top 10.', '2005-03-08 08:55:47.000000', NULL, 1),
(1214554, 152320, 29797, '<td valign="top">I like the little bit of brush and shore in the foreground, it adds a lot of depth. Nice shot.</td>', 'I like the little bit of brush and shore in the foreground, it adds a lot of depth. Nice shot.', '2005-03-08 09:07:26.000000', NULL, 1),
(1214564, 153109, 30857, '<td valign="top">Dramatic sky, good composition and light ... this is a beautiful picture ....<br/>Good luck!!</td>', 'Dramatic sky, good composition and light ... this is a beautiful picture ....Good luck!!', '2005-03-08 09:12:34.000000', NULL, 1),
