INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1215191, 153192, 33629, '<td valign="top">This is fabulous! the detail is splendid - the composition, the contrast the gradation in tonality is all mesmerizing.</td>', 'This is fabulous! the detail is splendid - the composition, the contrast the gradation in tonality is all mesmerizing.', '2005-03-08 14:22:25.000000', NULL, 1),
(1215192, 153394, 23478, '<td valign="top">Interesting photo, but it seems OOF to me.</td>', 'Interesting photo, but it seems OOF to me.', '2005-03-08 14:24:14.000000', NULL, 1),
(1215194, 153084, 23478, '<td valign="top">Excellent perspective, lighting, and contrast.</td>', 'Excellent perspective, lighting, and contrast.', '2005-03-08 14:25:28.000000', NULL, 1),
(1215196, 153392, 327, '<td valign="top">Fantastic tone, light and subject.</td>', 'Fantastic tone, light and subject.', '2005-03-08 14:26:41.000000', NULL, 1),
(1215209, 153232, 14028, '<td valign="top">wow.great shot! good tones and excellent composition. 9</td>', 'wow.great shot! good tones and excellent composition. 9', '2005-03-08 14:39:24.000000', NULL, 1),
