(1215219, 152894, 14028, '<td valign="top">lovely tones and texture.congrats. just regret the composition a bit. 6</td>', 'lovely tones and texture.congrats. just regret the composition a bit. 6', '2005-03-08 14:46:21.000000', NULL, 1),
(1215242, 152610, 14028, '<td valign="top">good shot, like the sense of movement in it.congrats. 8</td>', 'good shot, like the sense of movement in it.congrats. 8', '2005-03-08 14:59:15.000000', NULL, 1),
(1215256, 152623, 18191, '<td valign="top">Hopefully a winner...great tones and great exposure --- lovely shot! Good use of diagonals too,...they are subtle but effective.</td>', 'Hopefully a winner...great tones and great exposure --- lovely shot! Good use of diagonals too,...they are subtle but effective.', '2005-03-08 15:11:23.000000', NULL, 1),
(1215268, 152044, 18191, '<td valign="top">Great shot in a tricky metering situation. Very well done... one of my few tens.</td>', 'Great shot in a tricky metering situation. Very well done... one of my few tens.', '2005-03-08 15:16:14.000000', NULL, 1),
(1215269, 153364, 18191, '<td valign="top">Triplets...hot...</td>', 'Triplets...hot...', '2005-03-08 15:16:46.000000', NULL, 1),
(1215273, 151420, 31440, '<td valign="top">Needs more dynamic range</td>', 'Needs more dynamic range', '2005-03-08 15:18:42.000000', NULL, 1),
