(1215369, 153222, 31443, '<td valign="top">Good textures but lacks contrast in some places</td>', 'Good textures but lacks contrast in some places', '2005-03-08 16:14:56.000000', NULL, 1),
(1215372, 153361, 31443, '<td valign="top">Minimalist, don´t know if that was one of AA themes?</td>', 'Minimalist, don´t know if that was one of AA themes?', '2005-03-08 16:17:34.000000', NULL, 1),
(1215374, 152042, 18194, '<td valign="top">You highlights are pretty much blown out.</td>', 'You highlights are pretty much blown out.', '2005-03-08 16:18:36.000000', NULL, 1),
(1215380, 153219, 18194, '<td valign="top">Well as a start this is not what I think of as Adams style.  As a photo of a star field it is ot all that interesting. At least the focus is good.</td>', 'Well as a start this is not what I think of as Adams style.  As a photo of a star field it is ot all that interesting. At least the focus is good.', '2005-03-08 16:21:24.000000', NULL, 1),
(1215388, 153016, 18194, '<td valign="top">A bit under exposed</td>', 'A bit under exposed', '2005-03-08 16:26:28.000000', NULL, 1),
(1215390, 153404, 18194, '<td valign="top">I love it..9</td>', 'I love it..9', '2005-03-08 16:26:48.000000', NULL, 1),
(1215392, 153236, 18194, '<td valign="top">This is very under exposed, the exposure could easily be fixed using level in an editing program.</td>', 'This is very under exposed, the exposure could easily be fixed using level in an editing program.', '2005-03-08 16:28:14.000000', NULL, 1),
