(1215593, 152861, 20941, '<td valign="top">very cool image well presented in b/w</td>', 'very cool image well presented in b/w', '2005-03-08 18:31:36.000000', NULL, 1),
(1215635, 151656, 7810, '<td valign="top">Nice scene  ... woul love to see a bit more definition in the foreground... nice sky</td>', 'Nice scene  ... woul love to see a bit more definition in the foreground... nice sky', '2005-03-08 19:03:42.000000', NULL, 1),
