(1219649, 153236, 11843, '<td valign="top">Beautiful landscape! Excellent perspective and dof. I feel it lacks the overall tonal range for it to be in the AA style. 7</td>', 'Beautiful landscape! Excellent perspective and dof. I feel it lacks the overall tonal range for it to be in the AA style. 7', '2005-03-10 11:38:24.000000', NULL, 1),
(1219651, 152852, 27562, '<td valign="top">My pick for the best of the challenge.  Great Work.</td>', 'My pick for the best of the challenge.  Great Work.', '2005-03-10 11:38:44.000000', NULL, 1),
