(1219657, 152190, 11843, '<td valign="top">Very nice! 6</td>', 'Very nice! 6', '2005-03-10 11:39:50.000000', NULL, 1),
(1219658, 151791, 11843, '<td valign="top">Very nice! 6</td>', 'Very nice! 6', '2005-03-10 11:40:13.000000', NULL, 1),
(1219661, 153444, 11843, '<td valign="top">Great view! Beautiful!</td>', 'Great view! Beautiful!', '2005-03-10 11:40:45.000000', NULL, 1),
(1219664, 153117, 11843, '<td valign="top">I like this shot. It has good tonal range. Not sure what was to the right of the chapel, but I wish I could see more of the mountain and less of the spruce tree. 6</td>', 'I like this shot. It has good tonal range. Not sure what was to the right of the chapel, but I wish I could see more of the mountain and less of the spruce tree. 6', '2005-03-10 11:42:25.000000', NULL, 1),
(1219668, 152494, 11843, '<td valign="top">This is my second look at this shot. Gonna bump you up a little. Very good tonal range and excellent dof. 7</td>', 'This is my second look at this shot. Gonna bump you up a little. Very good tonal range and excellent dof. 7', '2005-03-10 11:43:41.000000', NULL, 1),
(1219669, 152992, 11843, '<td valign="top">This is a beautiful shot! But, i feel it lacks the range of tones needed to be in the AA style. 7</td>', 'This is a beautiful shot! But, i feel it lacks the range of tones needed to be in the AA style. 7', '2005-03-10 11:44:32.000000', NULL, 1),
(1219671, 153503, 11843, '<td valign="top">Nice range of tones!</td>', 'Nice range of tones!', '2005-03-10 11:45:01.000000', NULL, 1),
(1219673, 153233, 11843, '<td valign="top">Very nice work! 7</td>', 'Very nice work! 7', '2005-03-10 11:46:04.000000', NULL, 1),
(1219677, 153392, 32321, '<td valign="top">WOW! I like the fact that the background and sky are the 4th and 5th thing that catches my eye</td>', 'WOW! I like the fact that the background and sky are the 4th and 5th thing that catches my eye', '2005-03-10 11:47:16.000000', NULL, 1),
(1219678, 153291, 11843, '<td valign="top">Coming around on my second look and I am bumping this one up! Excellent tones and dof. 8</td>', 'Coming around on my second look and I am bumping this one up! Excellent tones and dof. 8', '2005-03-10 11:47:17.000000', NULL, 1),
(1219680, 152858, 24846, '<td valign="top">Ahh, a refreshing cityscape. I like this alot. A wide tonal range from the clouds to the watercraft. I like how you captured the wake of the boat, it really adds to the depth. Much detail to take in. IMO you''ve captured a good representation of AA''s techniques and ranges. You''ve met the challenge well in that the purpose was to emulate AA not neccesarily try to duplicate it, othewise you may have journeyed out to Ayers Rock. Good luck with this well composed compositon that gets high marks from me (despite my submitting a landscape, lol).</td>', 'Ahh, a refreshing cityscape. I like this alot. A wide tonal range from the clouds to the watercraft. I like how you captured the wake of the boat, it really adds to the depth. Much detail to take in. IMO you''ve captured a good representation of AA''s techniques and ranges. You''ve met the challenge well in that the purpose was to emulate AA not neccesarily try to duplicate it, othewise you may have journeyed out to Ayers Rock. Good luck with this well composed compositon that gets high marks from me (despite my submitting a landscape, lol).', '2005-03-10 11:47:46.000000', NULL, 1),
(1219682, 153148, 11843, '<td valign="top">Very good shot! Excellent details and dof. 7</td>', 'Very good shot! Excellent details and dof. 7', '2005-03-10 11:48:17.000000', NULL, 1),
(1219686, 152212, 32321, '<td valign="top">Good subject. I would have liked to see more contrast in the clouds. Great contrast and detail in the stump!</td>', 'Good subject. I would have liked to see more contrast in the clouds. Great contrast and detail in the stump!', '2005-03-10 11:49:10.000000', NULL, 1),
(1219689, 153434, 11843, '<td valign="top">Beautiful shot! Horizon is off a bit. Excellent tonal range. 7</td>', 'Beautiful shot! Horizon is off a bit. Excellent tonal range. 7', '2005-03-10 11:49:34.000000', NULL, 1),
(1219694, 153329, 11843, '<td valign="top">A wonderful image! Good tonal range.</td>', 'A wonderful image! Good tonal range.', '2005-03-10 11:50:27.000000', NULL, 1),
(1219695, 152894, 32321, '<td valign="top">Landscape is nice. Would have liked to see more contrast in the clouds</td>', 'Landscape is nice. Would have liked to see more contrast in the clouds', '2005-03-10 11:50:35.000000', NULL, 1),
(1219696, 153245, 11843, '<td valign="top">Very nice landscape!</td>', 'Very nice landscape!', '2005-03-10 11:50:51.000000', NULL, 1),
