(1219719, 152802, 11843, '<td valign="top">Good range of tones! Excellent cityscape.</td>', 'Good range of tones! Excellent cityscape.', '2005-03-10 11:58:11.000000', NULL, 1),
(1219720, 152213, 11843, '<td valign="top">Very nice image! Good tones.</td>', 'Very nice image! Good tones.', '2005-03-10 11:58:38.000000', NULL, 1),
