(1219724, 152989, 11843, '<td valign="top">Excellent landscape shot with very good tonal range and details.</td>', 'Excellent landscape shot with very good tonal range and details.', '2005-03-10 11:59:27.000000', NULL, 1),
(1219733, 152702, 32321, '<td valign="top">Great subject. Found sky and foreground too dark.</td>', 'Great subject. Found sky and foreground too dark.', '2005-03-10 12:01:56.000000', NULL, 1),
