(1220702, 152044, 10818, '<td valign="top">Great contrasts with the black headstones and white snow.  Wonderful photo.</td>', 'Great contrasts with the black headstones and white snow.  Wonderful photo.', '2005-03-10 19:10:21.000000', NULL, 1),
(1220708, 152614, 10818, '<td valign="top">Nothing sucks about this photo, I really like it.  Your scoring would be higher without that title, but I bet your comments are certainly more.  :)</td>', 'Nothing sucks about this photo, I really like it.  Your scoring would be higher without that title, but I bet your comments are certainly more.  :)', '2005-03-10 19:13:07.000000', NULL, 1),
(1220713, 152330, 10818, '<td valign="top">Fantastic shot, beautiful colors !  The moon in the right corner is a nice touch.  I wont mention the obvious.</td>', 'Fantastic shot, beautiful colors !  The moon in the right corner is a nice touch.  I wont mention the obvious.', '2005-03-10 19:20:18.000000', NULL, 1),
(1220722, 152699, 3306, '<td valign="top">Would have done very well in the Light on White challenge.</td>', 'Would have done very well in the Light on White challenge.', '2005-03-10 19:27:20.000000', NULL, 1),
(1220731, 153289, 10818, '<td valign="top">Fabulous photo, the cows really bring perspective to the shot.  Pretty rolling hill and nice contrasts.</td>', 'Fabulous photo, the cows really bring perspective to the shot.  Pretty rolling hill and nice contrasts.', '2005-03-10 19:32:45.000000', NULL, 1),
(1220747, 153109, 10818, '<td valign="top">Looks like a great time to take this photo, the light on the rock gives a great contrast of dark and light,  Wonderful photo.</td>', 'Looks like a great time to take this photo, the light on the rock gives a great contrast of dark and light,  Wonderful photo.', '2005-03-10 19:41:12.000000', NULL, 1),
