(1224068, 152854, 33520, '<td valign="top">Beautiful A A style close up! Well done! 10</td>', 'Beautiful A A style close up! Well done! 10', '2005-03-13 08:17:23.000000', NULL, 1),
(1224069, 153030, 24212, '<td valign="top">The sky is excellent. I do feel, however, that the foreground could do with a bit more sharpening.</td>', 'The sky is excellent. I do feel, however, that the foreground could do with a bit more sharpening.', '2005-03-13 08:17:43.000000', NULL, 1),
